@SpringBootTest @AutoConfigureMockMvc @ActiveProfiles("test")
class AcademicCycleIntegrationTests {
 @Autowired MockMvc mvc;@Autowired ObjectMapper json;@Autowired JdbcTemplate jdbc;@Autowired org.springframework.context.ApplicationContext context;
 @MockitoBean DocumentStoragePort storage;@MockitoBean BlockchainAnchorPort blockchain;
 final Map<String,byte[]> blobs=new ConcurrentHashMap<>();static final String PASSWORD="CycleTestPassword123!";
 record Org(String token,String id,String slug){}record Student(String token,String id,String code){}
 @BeforeEach void files(){blobs.clear();when(storage.store(anyString(),any(),anyString())).thenAnswer(i->{blobs.put(i.getArgument(0),i.getArgument(1));return i.getArgument(0);});when(storage.load(anyString())).thenAnswer(i->blobs.get(i.<String>getArgument(0)));when(blockchain.anchor(any(),any(),any())).thenReturn("pending:cycle");}
 JsonNode call(String method,String path,String token,Object body,int expected)throws Exception{var builder=org.springframework.test.web.servlet.request.MockMvcRequestBuilders.request(org.springframework.http.HttpMethod.valueOf(method),path).header("Authorization","Bearer "+token);if(body!=null)builder.contentType(MediaType.APPLICATION_JSON).content(json.writeValueAsString(body));var response=mvc.perform(builder).andExpect(status().is(expected)).andReturn().getResponse();return response.getContentAsString().isEmpty()?json.createObjectNode():json.readTree(response.getContentAsString());}
 Org org()throws Exception{String slug="cycle-"+UUID.randomUUID();var r=call("POST","/api/auth/register","",Map.of("organizationName","Institución de prueba","organizationSlug",slug,"institutionType","UNIVERSIDAD","email","admin@example.test","password",PASSWORD),201);ApprovedOrganizationFixture.approve(r,context);return new Org(r.get("token").asText(),r.get("tenantId").asText(),slug);}
 Student student()throws Exception{var r=call("POST","/api/auth/student/register","",Map.of("email",UUID.randomUUID()+"@example.test","password",PASSWORD,"fullName","Estudiante de prueba","country","BO","documentType","CI","documentNumber",UUID.randomUUID().toString(),"dateOfBirth","2000-05-12","department","La Paz"),201);String token=r.get("token").asText();var own=call("GET","/api/me/profile",token,null,200);jdbc.update("update student_accounts set email_verified=true where id=?",UUID.fromString(own.get("id").asText()));return new Student(token,own.get("id").asText(),own.get("searchCode").asText());}
 JsonNode record(Org org,Student s)throws Exception{call("POST","/api/students/redeem",org.token,Map.of("code",s.code),200);var p=call("POST","/api/institution/academic/programs",org.token,Map.of("name","Curso de prueba","kind","Curso","period","Gestión 2026","requirements","Constancia de participación","active",true),201);return call("POST","/api/institution/academic/records",org.token,Map.of("studentId",s.id,"programId",p.get("id").asText(),"registrationCode","MAT-"+UUID.randomUUID(),"enrolledOn","2026-01-10"),201);}
 String reviewer(Org org)throws Exception{var role=call("POST","/api/access/roles",org.token,Map.of("name","Revisor académico","permissions",List.of("REQUEST_VIEW","REQUEST_REVIEW")),201);String email="reviewer@example.test";call("POST","/api/access/users",org.token,Map.of("fullName","Revisor Prueba","email",email,"password",PASSWORD,"roleIds",List.of(role.get("id").asText())),201);return call("POST","/api/auth/login","",Map.of("organizationSlug",org.slug,"email",email,"password",PASSWORD),200).get("token").asText();}
 JsonNode template(Org org,String previous,String body)throws Exception{var input=new HashMap<String,Object>(Map.of("name","Plantilla de prueba","credentialType","CERTIFICADO","heading","Certificado","bodyText",body,"orientation","LANDSCAPE"));if(previous!=null)input.put("previousVersionId",previous);return call("POST","/api/institution/templates",org.token,input,201);}
 JsonNode request(Student s,JsonNode record,String template)throws Exception{var body=new HashMap<String,Object>(Map.of("recordId",record.get("id").asText(),"credentialType","CERTIFICADO","title","Formación académica","message","Solicitud de prueba"));if(template!=null)body.put("templateVersionId",template);return call("POST","/api/me/credential-requests",s.token,body,201);}
 JsonNode action(String token,String id,String action,int expected)throws Exception{return call("POST","/api/institution/credential-requests/"+id+"/actions",token,Map.of("action",action,"reason","Motivo de prueba válido"),expected);}
 JsonNode approve(Org org,String reviewer,String id)throws Exception{action(reviewer,id,"START",200);action(reviewer,id,"RECOMMEND",200);return action(org.token,id,"APPROVE",200);}
 byte[] document(Org org,String id)throws Exception{return mvc.perform(get("/api/credentials/"+id+"/document").header("Authorization","Bearer "+org.token)).andExpect(status().isOk()).andReturn().getResponse().getContentAsByteArray();}
 @Test void recordsAreScopedAndTheSameStudentHasTwoIndependentAcademicHistories()throws Exception{var a=org();var b=org();var s=student();var first=record(a,s);record(b,s);assertEquals(2,call("GET","/api/me/academic-records",s.token,null,200).size());var list=call("GET","/api/institution/academic/records",a.token,null,200);assertEquals(1,list.get("total").asInt());call("PATCH","/api/institution/academic/records/"+first.get("id").asText(),b.token,Map.of("status","COMPLETED","completedOn","2026-05-01"),404);assertEquals(1,jdbc.queryForObject("select count(*) from student_accounts where id=?",Integer.class,UUID.fromString(s.id)));var other=student();assertEquals(0,call("GET","/api/me/academic-records",other.token,null,200).size());}
 @Test void requestNeedsSeparateApprovalAndCompletesOnlyAfterActualSignedIssuance()throws Exception{var o=org();var s=student();var r=record(o,s);var t=template(o,null,"Por {{documentTitle}} en {{programName}}.");String review=reviewer(o);var request=request(s,r,t.get("id").asText());String id=request.get("id").asText();action(o.token,id,"APPROVE",409);action(review,id,"START",200);action(review,id,"RECOMMEND",200);action(review,id,"APPROVE",403);var approved=action(o.token,id,"APPROVE",200);String credential=approved.get("credentialId").asText();call("POST","/api/institution/signing-key/demo",o.token,Map.of("required",true),200);call("POST","/api/credentials/"+credential+"/generate-document",o.token,Map.of(),200);call("PATCH","/api/credentials/"+credential+"/issue",o.token,Map.of(),400);call("POST","/api/credentials/"+credential+"/sign",o.token,Map.of(),200);String key=UUID.randomUUID().toString();var issued=json.readTree(mvc.perform(patch("/api/credentials/"+credential+"/issue").header("Authorization","Bearer "+o.token).header("Idempotency-Key",key)).andExpect(status().isOk()).andReturn().getResponse().getContentAsString());mvc.perform(patch("/api/credentials/"+credential+"/issue").header("Authorization","Bearer "+o.token).header("Idempotency-Key",key)).andExpect(status().isOk());verify(blockchain,times(1)).anchor(any(),any(),any());assertEquals("FULFILLED",call("GET","/api/me/credential-requests",s.token,null,200).get(0).get("status").asText());byte[] bytes=document(o,credential);String object=jdbc.queryForObject("select document_object_key from credentials where id=?",String.class,UUID.fromString(credential));assertFalse(Arrays.equals(bytes,blobs.get(object)),"El objeto privado debe estar cifrado");String code=issued.get("verificationCode").asText();var result=mvc.perform(multipart("/api/public/credentials/"+code+"/check-document").file(new MockMultipartFile("file","certificate.pdf","application/pdf",bytes))).andExpect(status().isOk()).andExpect(jsonPath("$.hashMatches").value(true)).andExpect(jsonPath("$.signature.status").value("VALID")).andExpect(jsonPath("$.testSignature").value(true));byte[] changed=Arrays.copyOf(bytes,bytes.length+12);mvc.perform(multipart("/api/public/credentials/"+code+"/check-document").file(new MockMultipartFile("file","changed.pdf","application/pdf",changed))).andExpect(status().isOk()).andExpect(jsonPath("$.hashMatches").value(false));assertEquals("NOT_CHECKED",call("GET","/api/public/credentials/"+code,"",null,200).get("integrityStatus").asText());}
 @Test void administratorCannotApproveTheirOwnReviewAndDuplicatePendingRequestsAreRejected()throws Exception{var o=org();var s=student();var r=record(o,s);String id=request(s,r,null).get("id").asText();action(o.token,id,"START",200);action(o.token,id,"RECOMMEND",200);action(o.token,id,"APPROVE",400);call("POST","/api/me/credential-requests",s.token,Map.of("recordId",r.get("id").asText(),"credentialType","CERTIFICADO","title","Duplicada"),409);}
 @Test void observationsAllowPrivateCorrectionsButLockFilesDuringReview()throws Exception{var o=org();var s=student();var r=record(o,s);String review=reviewer(o),id=request(s,r,null).get("id").asText();var image=new MockMultipartFile("file","requisito.pdf","application/pdf",TestPdfs.create("Requisito privado"));mvc.perform(multipart("/api/me/credential-requests/"+id+"/attachments").file(image).header("Authorization","Bearer "+s.token)).andExpect(status().isOk());action(review,id,"START",200);mvc.perform(multipart("/api/me/credential-requests/"+id+"/attachments").file(image).header("Authorization","Bearer "+s.token)).andExpect(status().isConflict());action(review,id,"OBSERVE",200);call("PATCH","/api/me/credential-requests/"+id,s.token,Map.of("title","Título corregido","message","Corrección solicitada"),200);call("POST","/api/me/credential-requests/"+id+"/actions",s.token,Map.of("action","RESUBMIT"),200);assertEquals("SUBMITTED",call("GET","/api/me/credential-requests",s.token,null,200).get(0).get("status").asText());var other=student();call("POST","/api/me/credential-requests/"+id+"/actions",other.token,Map.of("action","WITHDRAW"),404);}
 @Test void correctionPreservesOriginalBytesAndPublishesReplacementOnlyAfterIssue()throws Exception{var o=org();var s=student();var r=record(o,s);String review=reviewer(o);String original=call("POST","/api/credentials",o.token,Map.of("studentId",s.id,"credentialType","CERTIFICADO","title","Documento original"),201).get("id").asText();call("POST","/api/credentials/"+original+"/generate-document",o.token,Map.of(),200);var issued=call("PATCH","/api/credentials/"+original+"/issue",o.token,Map.of(),200);byte[] originalBytes=document(o,original);String id=call("POST","/api/me/credentials/"+original+"/corrections",s.token,Map.of("recordId",r.get("id").asText(),"title","Documento corregido","reason","Corrección del título por error material"),201).get("id").asText();String replacement=approve(o,review,id).get("credentialId").asText();assertEquals("ISSUED",call("GET","/api/public/credentials/"+issued.get("verificationCode").asText(),"",null,200).get("status").asText());call("POST","/api/credentials/"+replacement+"/generate-document",o.token,Map.of(),200);var newer=call("PATCH","/api/credentials/"+replacement+"/issue",o.token,Map.of(),200);var old=call("GET","/api/public/credentials/"+issued.get("verificationCode").asText(),"",null,200);assertEquals("REVOKED",old.get("status").asText());assertEquals(newer.get("verificationCode").asText(),old.get("replacedByCode").asText());assertArrayEquals(originalBytes,document(o,original));}
 @Test void templatesHaveImmutableVersionsAndCannotBeBorrowedAcrossTenants()throws Exception{var a=org();var b=org();var s=student();var r=record(a,s);var v1=template(a,null,"Primera {{documentTitle}}");var v2=template(a,v1.get("id").asText(),"Segunda {{documentTitle}}");assertEquals(2,v2.get("version").asInt());assertEquals("Primera {{documentTitle}}",call("GET","/api/institution/templates",a.token,null,200).get(1).get("bodyText").asText());call("POST","/api/institution/templates",a.token,Map.of("name","No permitida","credentialType","CERTIFICADO","heading","Certificado","bodyText","{{password}}","orientation","LANDSCAPE"),400);mvc.perform(get("/api/institution/templates/"+v1.get("id").asText()+"/preview").header("Authorization","Bearer "+b.token)).andExpect(status().isNotFound());mvc.perform(get("/api/institution/templates/"+v1.get("id").asText()+"/preview").header("Authorization","Bearer "+a.token)).andExpect(status().isOk());var foreign=template(b,null,"De otra institución");call("POST","/api/me/credential-requests",s.token,Map.of("recordId",r.get("id").asText(),"credentialType","CERTIFICADO","title","Prueba","templateVersionId",foreign.get("id").asText()),404);}
 @Test void profileChangesAndWithdrawnApprovalBlockIssueWithoutTouchingThePdf()throws Exception{var o=org();var s=student();var r=record(o,s);String review=reviewer(o),id=request(s,r,null).get("id").asText();String c=approve(o,review,id).get("credentialId").asText();call("POST","/api/credentials/"+c+"/generate-document",o.token,Map.of(),200);byte[] previous=document(o,c);call("POST","/api/me/credential-requests/"+id+"/actions",s.token,Map.of("action","WITHDRAW"),200);call("PATCH","/api/credentials/"+c+"/issue",o.token,Map.of(),400);assertArrayEquals(previous,document(o,c));verify(blockchain,never()).anchor(any(),any(),any());}
 @Test void concurrentApprovalCreatesExactlyOneDraft()throws Exception{var o=org();var s=student();var r=record(o,s);String review=reviewer(o),id=request(s,r,null).get("id").asText();action(review,id,"START",200);action(review,id,"RECOMMEND",200);var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);try{Callable<Integer> approve=()->{start.await();return mvc.perform(post("/api/institution/credential-requests/"+id+"/actions").header("Authorization","Bearer "+o.token).contentType(MediaType.APPLICATION_JSON).content("{\"action\":\"APPROVE\"}")).andReturn().getResponse().getStatus();};var a=pool.submit(approve);var b=pool.submit(approve);start.countDown();var states=new ArrayList<>(List.of(a.get(20,TimeUnit.SECONDS),b.get(20,TimeUnit.SECONDS)));Collections.sort(states);assertEquals(List.of(200,409),states);assertEquals(1,jdbc.queryForObject("select count(*) from credentials where source_request_id=?",Integer.class,UUID.fromString(id)));}finally{pool.shutdownNow();}}
 @Test void consentWithdrawalHidesInstitutionalQueuesAndKeepsOwnAcademicHistory()throws Exception{
  var o=org();var s=student();var r=record(o,s);String id=request(s,r,null).get("id").asText();
  var consents=call("GET","/api/me/consents",s.token,null,200);String consent=consents.get(0).get("id").asText();call("DELETE","/api/me/consents/"+consent,s.token,null,200);
  assertEquals(0,call("GET","/api/institution/academic/records",o.token,null,200).get("total").asInt());assertEquals(0,call("GET","/api/institution/credential-requests",o.token,null,200).get("total").asInt());call("GET","/api/institution/credential-requests/"+id,o.token,null,404);
  assertEquals(1,call("GET","/api/me/academic-records",s.token,null,200).size());assertEquals(1,call("GET","/api/me/credential-requests",s.token,null,200).size());
 }
 @Test void approvedTemplateCannotBeReplacedAndChangedProfileBlocksIssue()throws Exception{
  var o=org();var s=student();var r=record(o,s);String review=reviewer(o);var first=template(o,null,"Primera plantilla");var second=template(o,null,"Otra plantilla");String id=request(s,r,first.get("id").asText()).get("id").asText(),c=approve(o,review,id).get("credentialId").asText();
  call("POST","/api/credentials/"+c+"/generate-document",o.token,Map.of("templateVersionId",second.get("id").asText()),400);call("POST","/api/credentials/"+c+"/generate-document",o.token,Map.of(),200);
  var current=call("GET","/api/me/profile",s.token,null,200);call("PATCH","/api/me/profile",s.token,Map.of("fullName","Nuevo nombre completo","country","BO","documentType","CI","documentNumber",current.get("documentNumber").asText(),"dateOfBirth","2000-05-12","department","La Paz"),200);
  call("PATCH","/api/credentials/"+c+"/issue",o.token,Map.of(),400);verify(blockchain,never()).anchor(any(),any(),any());
 }
 @Test void issuanceSerializesWithProfileEditsAndKeepsTheIssuedHolderSnapshot()throws Exception{
  var o=org();var s=student();var r=record(o,s);String review=reviewer(o),id=request(s,r,null).get("id").asText(),c=approve(o,review,id).get("credentialId").asText();call("POST","/api/credentials/"+c+"/generate-document",o.token,Map.of(),200);
  var profile=call("GET","/api/me/profile",s.token,null,200);var entered=new CountDownLatch(1);var release=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
  doAnswer(i->{entered.countDown();assertTrue(release.await(10,TimeUnit.SECONDS));return blobs.get(i.<String>getArgument(0));}).when(storage).load(anyString());
  try{var issue=pool.submit(()->call("PATCH","/api/credentials/"+c+"/issue",o.token,Map.of(),200));assertTrue(entered.await(10,TimeUnit.SECONDS));var edit=pool.submit(()->call("PATCH","/api/me/profile",s.token,Map.of("fullName","Perfil modificado después","country","BO","documentType","CI","documentNumber",profile.get("documentNumber").asText(),"dateOfBirth","2000-05-12","department","La Paz"),200));assertThrows(TimeoutException.class,()->edit.get(200,TimeUnit.MILLISECONDS));release.countDown();assertEquals("ISSUED",issue.get(10,TimeUnit.SECONDS).get("status").asText());edit.get(10,TimeUnit.SECONDS);assertEquals("Estudiante de prueba",call("GET","/api/me/credentials",s.token,null,200).get(0).get("holderName").asText());}finally{release.countDown();pool.shutdownNow();}
 }
}
